1427	/// Returns `true` if `comment` is a [Closure type comment](https://github.com/google/closure-compiler/wiki/Types-in-the-Closure-Type-System)
1428	/// or [TypeScript type comment](https://www.typescriptlang.org/docs/handbook/jsdoc-supported-types.html#type)
1429	pub(crate) fn is_type_comment(comment: &SyntaxTriviaPieceComments<JsLanguage>) -> bool {
1430	    let text = comment.text();
1431	
1432	    // Must be a `/**` comment
1433	    if !text.starts_with("/**") {
1434	        return false;
1435	    }
1436	
1437	    text.trim_start_matches("/**")
1438	        .trim_end_matches("*/")
1439	        .split_whitespace()
1440	        .any(|word| {
1441	            match word
1442	                .strip_prefix("@type")
1443	                .or_else(|| word.strip_prefix("@satisfies"))
1444	            {
1445	                Some(after) => after.is_empty() || after.starts_with('{'),
1446	                None => false,
1447	            }
1448	        })
1449	}
