52	#[test]
53	fn test_trailing_newline_enabled() {
54	    let src = r#"const a = 1;"#;
55	    let source_type = JsFileSource::js_module();
56	    let tree = parse(src, source_type, JsParserOptions::default());
57	    let options =
58	        JsFormatOptions::new(source_type).with_trailing_newline(TrailingNewline::from(true));
59	
60	    let doc = format_node(options, &tree.syntax(), false).unwrap();
61	    let result = doc.print().unwrap();
62	
63	    // With trailing newline enabled (default), should end with newline
64	    assert!(
65	        result.as_code().ends_with('\n'),
66	        "Expected code to end with newline"
67	    );
68	}
