71	fn test_trailing_newline_disabled() {
72	    let src = r#"const a = 1;"#;
73	    let source_type = JsFileSource::js_module();
74	    let tree = parse(src, source_type, JsParserOptions::default());
75	    let options =
76	        JsFormatOptions::new(source_type).with_trailing_newline(TrailingNewline::from(false));
77	
78	    let doc = format_node(options, &tree.syntax(), false).unwrap();
79	    let result = doc.print().unwrap();
80	
81	    // With trailing newline disabled, should NOT end with newline
82	    assert!(
83	        !result.as_code().ends_with('\n'),
84	        "Expected code to NOT end with newline"
85	    );
86	    assert!(
87	        !result.as_code().ends_with('\r'),
88	        "Expected code to NOT end with carriage return"
89	    );
