---
/// Keeps trailing line comments on a `case` clause's line when the clause's
/// consequent is a block statement.
///
/// ```javascript
/// switch (key) {
///   case foo: // comment
///   case bar: {
///     work();
///   }
/// }
/// ```
///
/// When such a clause is formatted, the opening brace of the block hugs the
/// `case` line and the trailing comment is printed right after it
/// (`case bar: { // comment`). Parsing that output again attaches the comment
/// inside the block as a leading comment of the first statement, which would
/// move it onto its own line and break idempotence. To keep the comment on the
/// `case` line, re-attach it as a trailing comment of the clause's test
/// expression, matching how it is placed when the comment precedes the opening
/// brace.
fn handle_switch_case_clause_comment(
    comment: DecoratedComment<JsLanguage>,
) -> CommentPlacement<JsLanguage> {
    // Only relevant for line comments that sit on the same line as the block's
    // opening brace, i.e. end-of-line comments with nothing preceding them
    // inside the block. Own-line comments are handled by the default placement
    // so they remain inside the block.
    if !comment.kind().is_line() || comment.preceding_node().is_some() {
        return CommentPlacement::Default(comment);
    }

    let Some(block) = JsBlockStatement::cast_ref(comment.enclosing_node()) else {
        return CommentPlacement::Default(comment);
    };

    // The block must be a statement of a `case` clause's consequent. The block
    // is nested inside the clause's `JsStatementList`, so the clause is its
    // grandparent.
    let Some(case_clause) = block
        .syntax()
        .parent()
        .filter(|parent| parent.kind() == JsSyntaxKind::JS_STATEMENT_LIST)
        .and_then(|list| list.parent())
        .and_then(JsCaseClause::cast)
    else {
        return CommentPlacement::Default(comment);
    };

    match case_clause.test() {
        Ok(test) => CommentPlacement::trailing(test.into_syntax(), comment),
        Err(_) => CommentPlacement::Default(comment),
    }
}

